// 自动生成的游戏音频（base64编码的WAV文件）
const GAME_AUDIO = {
    "bgm_peaceful": "",
    "bgm_battle": "",
    "bgm_dark": "",
    "bgm_majestic": "",
    "bgm_ethereal": "",
    "bgm_dungeon": "",
    "bgm_sect": "",
    "bgm_boss": "",
    "sfx_attack": "",
    "sfx_hit": "",
    "sfx_skill": "",
    "sfx_crit": "",
    "sfx_victory": "",
    "sfx_defeat": "",
    "sfx_breakthrough": "",
    "sfx_click": "",
    "sfx_item": "",
    "sfx_open": "",
    "sfx_close": "",
    "sfx_heal": "",
    "sfx_enhance": "",
    "sfx_enhance_fail": "",
    "sfx_pet_catch": "",
    "sfx_dungeon_enter": "",
    "sfx_levelup": "",
    "sfx_coin": "",
    "sfx_warning": "",
    "sfx_combo": "",
    "sfx_use_item": "",
    "sfx_teleport": "",
    "sfx_alchemy": "",
    "sfx_auction": "",
    "sfx_sect": "",
};


// 音频管理器
class AudioManager {
    constructor() {
        this.audioCtx = null;
        this.buffers = {};
        this.bgmSource = null;
        this.bgmGain = null;
        this.sfxGain = null;
        this.bgmVolume = 0.3;
        this.sfxVolume = 0.5;
        this.muted = false;
        this.loaded = false;
    }

    async init() {
        try {
            this.audioCtx = new (window.AudioContext || window.webkitAudioContext)();
            this.bgmGain = this.audioCtx.createGain();
            this.bgmGain.gain.value = this.bgmVolume;
            this.bgmGain.connect(this.audioCtx.destination);
            this.sfxGain = this.audioCtx.createGain();
            this.sfxGain.gain.value = this.sfxVolume;
            this.sfxGain.connect(this.audioCtx.destination);
            await this._loadAll();
            this.loaded = true;
        } catch (e) {
            console.warn('Audio init failed:', e);
        }
    }

    async _loadAll() {
        for (const [name, b64] of Object.entries(GAME_AUDIO)) {
            try {
                const binary = atob(b64);
                const bytes = new Uint8Array(binary.length);
                for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
                this.buffers[name] = await this.audioCtx.decodeAudioData(bytes.buffer);
            } catch (e) {
                // skip failed audio
            }
        }
    }

    playSfx(name) {
        if (!this.loaded || this.muted || !this.buffers[name]) return;
        try {
            const source = this.audioCtx.createBufferSource();
            source.buffer = this.buffers[name];
            source.connect(this.sfxGain);
            source.start(0);
        } catch (e) {}
    }

    playBgm(name) {
        if (!this.loaded || !this.buffers[name]) return;
        this.stopBgm();
        try {
            this.bgmSource = this.audioCtx.createBufferSource();
            this.bgmSource.buffer = this.buffers[name];
            this.bgmSource.loop = true;
            this.bgmSource.connect(this.bgmGain);
            this.bgmSource.start(0);
        } catch (e) {}
    }

    stopBgm() {
        if (this.bgmSource) {
            try { this.bgmSource.stop(); } catch (e) {}
            this.bgmSource = null;
        }
    }

    setBgmVolume(v) { this.bgmVolume = v; if (this.bgmGain) this.bgmGain.gain.value = v; }
    setSfxVolume(v) { this.sfxVolume = v; if (this.sfxGain) this.sfxGain.gain.value = v; }
    toggleMute() { this.muted = !this.muted; if (this.bgmGain) this.bgmGain.gain.value = this.muted ? 0 : this.bgmVolume; }
}

const audioManager = new AudioManager();
